    if (g != 1) return -1; // Inverse doesn't exist
    return (x % m + m) % m;
}

vector<long long> get_factors(long long n) {
    vector<long long> factors;
    for (long long i = 2; i * i <= n; i++) {
        while (n % i == 0) {
            factors.push_back(i);
            n /= i;
        }
    }
    if (n > 1) factors.push_back(n);
    return factors;
}
